import { createElement } from "react"
import { NextGuideOgCard } from "nextguide/og"
import { ImageResponse } from "next/og"
import { docs, site, appearance } from "@/lib/nextguide"

export async function generateStaticParams() {
  const paths = await docs.getPagePaths()
  return paths.map((path) => {
    const slug = path.split("/").filter(Boolean)
    if (!slug.length) slug.push("index")
    slug[slug.length - 1] += ".png"
    return { slug }
  })
}

export async function GET(_request: Request, { params }: { params: Promise<{ slug: string[] }> }) {
  const routeSlug = (await params).slug
  const parts = [...routeSlug]
  parts[parts.length - 1] = parts[parts.length - 1].replace(/\.png$/, "")
  const joined = parts.join("/")
  const slug = joined === "index" ? "" : joined
  const frontmatter = await docs.getFrontmatter({ slug })
  return new ImageResponse(
    createElement(NextGuideOgCard, {
      siteName: site.name,
      brandMark: "site",
      title: String(frontmatter.title ?? "Documentation"),
      description: String(frontmatter.description ?? site.description ?? ""),
      section: "Documentation",
      appearance: appearance.mode,
      accent: appearance.accent,
    }),
    { width: 1200, height: 630 },
  )
}
